The telemetry points to one fault, on the search→rate connection. I'm reporting it as `network_delay`, but no per-connection network metrics exist in this case, so that kind rests on the trace timing alone.

```json
{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH c AS (SELECT trace_id, span_id, time, duration, 'abn' p FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Client' UNION ALL SELECT trace_id, span_id, time, duration, 'norm' FROM normal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Client'), s AS (SELECT trace_id, parent_span_id, time, duration, 'abn' p FROM abnormal_traces WHERE service_name='rate' AND attr_span_kind='Server' UNION ALL SELECT trace_id, parent_span_id, time, duration, 'norm' FROM normal_traces WHERE service_name='rate' AND attr_span_kind='Server') SELECT c.p, count(*) n, round(avg(c.duration/1e6),1) client_ms, round(avg(s.duration/1e6),2) server_ms, round(avg(epoch(s.time)-epoch(c.time))*1000,1) start_gap_ms, round(avg((epoch(c.time)+c.duration/1e9)-(epoch(s.time)+s.duration/1e9))*1000,1) end_gap_ms FROM c JOIN s ON c.trace_id=s.trace_id AND c.span_id=s.parent_span_id AND c.p=s.p GROUP BY c.p",
          "claim": "Search's GetRates client spans take ~1641ms in abnormal vs 0.7ms normal; the wait is before rate's server span starts (~1640ms gap), and rate's server span stays ~0.5ms."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, service_name, metric, count(*) n, round(avg(value),2) avg_v FROM abnormal_metrics_sum WHERE service_name IN ('search','rate') AND metric IN ('container.cpu.time','k8s.pod.uptime','k8s.pod.network.errors') GROUP BY 1,2,3 UNION ALL SELECT 'norm', service_name, metric, count(*), round(avg(value),2) FROM normal_metrics_sum WHERE service_name IN ('search','rate') AND metric IN ('container.cpu.time','k8s.pod.uptime','k8s.pod.network.errors') GROUP BY 1,2,3 ORDER BY 3,2,1",
          "claim": "Search and rate CPU, uptime and network errors are essentially unchanged from normal, so no pod or resource fault is present on either end."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,1) avg_ms, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='search' AND span_name IN ('search.Search/Nearby','rate.Rate/GetRates','geo.Geo/Nearby') GROUP BY 1,2,3",
          "claim": "Search's Nearby server span rises to ~1652ms avg, matching its slow GetRates client span to rate; its geo call stays ~0.5ms."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH c AS (SELECT trace_id, span_id, time, duration FROM abnormal_traces WHERE service_name='frontend' AND span_name='search.Search/Nearby' AND attr_span_kind='Client'), s AS (SELECT trace_id, parent_span_id, time, duration FROM abnormal_traces WHERE service_name='search' AND attr_span_kind='Server') SELECT count(*) n, round(avg(c.duration/1e6),1) frontend_client_ms, round(avg(s.duration/1e6),1) search_server_ms, round(avg(epoch(s.time)-epoch(c.time))*1000,1) start_gap_ms FROM c JOIN s ON c.trace_id=s.trace_id AND c.span_id=s.parent_span_id",
          "claim": "Frontend's Search call averages ~1663ms and matches search's server span (~1663ms) with near-zero gap, so the delay is inherited from search."
        }
      ]
    }
  ]
}
```

